-- 0175: B4-roles-1 (docs/_TODO/SAAS_FOUNDATION/LOG.md, taskdb #662), owner decision: separate DB
-- roles instead of a GUC flag for the staff bypass.
--
-- PROBLEM: every patient-wall policy created by 0169-0174 lets staff sessions through via
-- `NULLIF(current_setting('app.actor', true), '') = 'staff'` — a plain session GUC. ANY session
-- (a patient session included) can set `app.actor = 'staff'` itself via GUC injection and defeat
-- the patient wall entirely. GUCs are not a security boundary; DB role membership is.
--
-- FIX: replace the GUC check with a role-membership check via a new canonical helper function,
-- `app.is_staff()` (SECURITY INVOKER, STABLE) — `SELECT pg_has_role(current_user, 'app_staff',
-- 'MEMBER')`. `app_staff` is a fixed, canonical role name: the SINGLE place it is spelled out is
-- inside this function (not duplicated in any policy predicate or elsewhere in the renderer). The
-- matching roles (`app_staff` / `app_patient`, both LOGIN NOBYPASSRLS, `app_patient` deliberately
-- NOT granted membership in `app_staff`) are created by
-- deploy/postgres/p0-5b-role-split-staff-patient.sql (dormant — does not touch prod grants/DATABASE_URL,
-- see that file's own header). A session cannot forge role membership the way it could forge a GUC:
-- `SET ROLE app_staff` from a session authenticated as `app_patient` is rejected by Postgres itself
-- (proven live by docs/_TODO/SAAS_FOUNDATION/scripts/smoke-b4-roles-1-staff-role-boundary.mjs, scratch
-- DB only).
--
-- `rls-sql-renderer.mjs`'s `renderStaffActorCheck()` is the ONLY place any predicate embeds the
-- staff bypass — every wrapper (`renderStaffOrPatientPredicate`, `renderStaffOrPatientChainPredicate`,
-- `renderStaffOrConditionalPatientPredicate`, `renderStaffOrConditionalChainPatientPredicate`,
-- `renderStaffOrPolymorphicPatientPredicate`, and the enforce-mode fk_path branch in
-- p0-9-enforce-descriptors.mjs) calls through it. Changing that one function is therefore sufficient
-- to flip ALL patient-wall predicate shapes (direct column, chain, conditional/dual-role, conditional
-- chain, polymorphic) from the GUC check to `app.is_staff()` — this migration is the exact generated
-- output of re-running the same three per-schema generators used by 0169-0174, filtered to the tables
-- that declare ANY patient ownership (`rls-sql-renderer.mjs` `hasAnyPatientOwnership`):
--
--   node docs/_TODO/SAAS_FOUNDATION/scripts/p0-8-3-policy-targets.mjs --sql   (filtered to patient-owned)
--   node docs/_TODO/SAAS_FOUNDATION/scripts/p0-8-4-policy-targets.mjs --sql   (filtered to patient-owned)
--   node docs/_TODO/SAAS_FOUNDATION/scripts/p0-8-5-policy-targets.mjs --sql   (filtered to patient-owned)
--
-- 102 tables total (62 P0.8.3 public direct-org, 28 P0.8.4 public FK/denorm/polymorphic, 12 P0.8.5
-- integrator SCOPED) — the exact same 102 tables already carrying a patient-wall policy from
-- 0169-0174 (no table gains or loses patient ownership here, only the staff-bypass MECHANISM
-- changes). Org-only tables (no patient ownership) are untouched — they never called
-- renderStaffActorCheck() and are not part of this migration's DROP/CREATE set.
--
-- The `app` schema + `app.is_staff()` function are created FIRST (below), before any policy that
-- references them, so a fresh apply order never hits an undefined-function error.
--
-- Idempotent: `CREATE SCHEMA IF NOT EXISTS` / `CREATE OR REPLACE FUNCTION` are no-ops if already
-- current; `DROP POLICY IF EXISTS` + `CREATE POLICY` replaces each prior policy of the same name in
-- place (same policy names as 0169-0174 — this only changes the predicate body, not the name).
--
-- Rollback (ops): DROP POLICY IF EXISTS + re-CREATE the prior (GUC-based) predicate for these 102
-- tables (`git show <this file's previous commit>` for 0169-0174's CREATE POLICY statements), then
-- `DROP FUNCTION IF EXISTS app.is_staff()` (safe once no policy references it). No column/table
-- drop, no data change; safe to revert at any time.
--
-- Dormant in prod today: the app DB role still has BYPASSRLS (P0.5/B5 not flipped; the new
-- app_staff/app_patient roles from p0-5b are not wired into any runtime DATABASE_URL — B4-fanout
-- connection routing is a separate, owner-gated stage). This migration only changes what the policy
-- WOULD do under a NOBYPASSRLS session — proven via
-- docs/_TODO/SAAS_FOUNDATION/scripts/smoke-b4-roles-1-staff-role-boundary.mjs, scratch DB only.
--
-- HARDENING (post-merge audit, taskdb #662, 2026-07-11): the initial version of this migration let
-- `CREATE SCHEMA IF NOT EXISTS app` / `CREATE OR REPLACE FUNCTION app.is_staff()` silently keep the
-- OWNER of a pre-existing object (both statements are no-ops/replace-in-place, neither re-asserts
-- ownership). If a lower-trust role had squatted `app`/`app.is_staff()` before this migration first
-- ran, a migration executed with enough privilege to bypass ownership checks (e.g. as a superuser)
-- would replace the function body while leaving the squatter as owner, who could then silently
-- rewrite it back to `SELECT true` later. Fixed by reclaiming ownership unconditionally right after
-- each CREATE (`ALTER SCHEMA app OWNER TO CURRENT_USER` / `ALTER FUNCTION app.is_staff() OWNER TO
-- CURRENT_USER`, both harmless no-ops on a clean/idempotent run) plus an explicit `REVOKE CREATE ON
-- SCHEMA app FROM PUBLIC`. See inline comments below for the live scratch-DB proof.

CREATE SCHEMA IF NOT EXISTS app;

-- Hardening (B4-roles-1 audit fix #2, taskdb #662): `CREATE SCHEMA IF NOT EXISTS` and
-- `CREATE OR REPLACE FUNCTION` (below) both silently PRESERVE the owner of a pre-existing object --
-- they are no-ops/replace-in-place when the object already exists, they do not re-assert ownership.
-- If a lower-trust role had already squatted `app` / `app.is_staff()` before this migration first
-- ran (name-squatting ahead of the legitimate migration), a migration run with enough privilege to
-- bypass ownership checks (e.g. run as a superuser, which some deploy/bootstrap paths do) would
-- happily replace the function BODY while leaving OWNERSHIP with the attacker -- who could then
-- silently rewrite app.is_staff() back to `SELECT true` (or anything else) at any later time,
-- defeating the RLS bypass check without touching this migration again. Live-proven, scratch DB
-- only, 2026-07-11: a role squatting `app`/`app.is_staff()` (owned by the squatter) followed by this
-- migration's original CREATE SCHEMA IF NOT EXISTS + CREATE OR REPLACE FUNCTION, run as a
-- superuser-equivalent role, left `app.is_staff()` owned by the squatter with the new body installed
-- -- exactly the silent-takeover risk described above. (A non-superuser, non-owner migrator is
-- already blocked earlier, by Postgres's own "must be owner" check on CREATE OR REPLACE FUNCTION /
-- GRANT on a schema it doesn't own -- this ALTER ... OWNER TO closes the gap for the
-- superuser/elevated-migrator case, and is a harmless no-op on every clean/idempotent run where this
-- migration's own role already owns both objects.)
ALTER SCHEMA app OWNER TO CURRENT_USER;

-- Explicit belt-and-suspenders (CREATE SCHEMA already grants no privileges to PUBLIC by default):
-- re-assert this so schema app can never end up CREATE-able by PUBLIC -- the precondition for the
-- squatting attack above -- even after a future manual GRANT made outside of this migration file.
REVOKE CREATE ON SCHEMA app FROM PUBLIC;

-- CREATE SCHEMA grants NO privileges to PUBLIC by default (unlike the pre-existing `public` schema).
-- Without this, ANY non-superuser NOBYPASSRLS role (app_staff/app_patient included) evaluating a
-- policy that calls app.is_staff() gets a hard "permission denied for schema app" ERROR, not a
-- silent allow/deny -- found live by smoke-b4-roles-1-staff-role-boundary.mjs. USAGE only exposes
-- the ability to reference objects in the schema by name; EXECUTE on the function itself is granted
-- separately below.
GRANT USAGE ON SCHEMA app TO PUBLIC;

-- Canonical staff-bypass check (B4-roles-1, taskdb #662). SECURITY INVOKER (default, stated
-- explicitly): evaluates role membership of the CALLING session's current_user, never elevates
-- privilege. STABLE: current_user/role membership do not change within a single statement, so the
-- planner may fold repeated calls within one query. search_path is pinned to pg_catalog so this
-- function's body cannot be hijacked by a same-named object created earlier in a session's
-- search_path (it only ever needs the built-in pg_has_role/current_user).
CREATE OR REPLACE FUNCTION app.is_staff()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = pg_catalog
AS $$
  SELECT pg_has_role(current_user, 'app_staff', 'MEMBER');
$$;

-- Same ownership-reclaim reasoning as `ALTER SCHEMA app OWNER TO CURRENT_USER` above: CREATE OR
-- REPLACE FUNCTION replaces the BODY of a pre-existing function in place but does not touch its
-- OWNER, so a squatted app.is_staff() would keep the squatter's ownership even after this migration
-- "fixes" its body. No-op on a clean/idempotent run where this migration's role already owns it.
ALTER FUNCTION app.is_staff() OWNER TO CURRENT_USER;

COMMENT ON FUNCTION app.is_staff() IS
  'B4-roles-1 (taskdb #662): canonical staff-bypass check for patient-wall RLS policies. True iff '
  'the calling session''s current_user is (or is a member of) the fixed role app_staff, created by '
  'deploy/postgres/p0-5b-role-split-staff-patient.sql. This function is the SINGLE place the '
  '''app_staff'' role name is spelled out for RLS purposes -- do not duplicate the literal name in '
  'any policy predicate.';

GRANT EXECUTE ON FUNCTION app.is_staff() TO PUBLIC;

